#!/usr/bin/env python3
from pathlib import Path
import os,re,sys

if len(sys.argv)!=2:
    raise SystemExit('usage: compare-upstream-env.py /path/to/Plainwire')
root=Path(sys.argv[1])
if not root.is_dir(): raise SystemExit(f'not a directory: {root}')
pat=re.compile(r'PLAINWIRE_[A-Z0-9_]+')
seen=set()
for dp,dirs,files in os.walk(root):
    dirs[:]=[d for d in dirs if d not in {'.git','_build','node_modules'}]
    for fn in files:
        p=Path(dp)/fn
        if p.suffix not in {'.erl','.md','.example','.yaml','.yml','.config','.src'} and fn!='Caddyfile': continue
        try: seen.update(pat.findall(p.read_text(errors='ignore')))
        except OSError: pass
